CREATE TABLE nrs(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,nome varchar(250) NOT NULL);
CREATE TABLE funcionarios(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,nome varchar(100) NOT NULL,cpf varchar(11) NOT NULL,cargo varchar(40),setor varchar(40),permissoes varchar(10) NOT NULL,status varchar(2) NOT NULL,CONSTRAINT funcionarios_check CHECK(status IN ('At','Af','In') AND permissoes IN ('ADM','field','tst')));
CREATE TABLE funcionarios_nrs(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,funcionario_id bigint NOT NULL REFERENCES funcionarios(id),nr_id bigint REFERENCES nrs(id) ON UPDATE CASCADE);
CREATE TABLE epis(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,ca varchar(15),nome varchar(600) NOT NULL,lote varchar(20) NOT NULL,vencimento date NOT NULL,substituido boolean NOT NULL);
CREATE TABLE epi_funcionarios(epi_id bigint REFERENCES epis(id),funcionario_id bigint REFERENCES funcionarios(id));
CREATE TABLE dias_notificacao_epi(id bigint PRIMARY KEY,ca_ou_nr varchar(15) NOT NULL,dias_aviso integer NOT NULL,is_norma boolean NOT NULL);
CREATE TABLE dias_notificacao(LIKE dias_notificacao_epi INCLUDING ALL);
CREATE TABLE turmas_treinamento(id bigint PRIMARY KEY,nr varchar(250),nome varchar(250),data date,vencimento date);
CREATE TABLE presencas_treinamento(id bigint PRIMARY KEY,turma_id bigint REFERENCES turmas_treinamento(id),funcionario_id bigint REFERENCES funcionarios(id),presente boolean);
CREATE TABLE relatos_epi(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,epi_id bigint REFERENCES epis(id),funcionario_id bigint REFERENCES funcionarios(id),situacao varchar(255),comentario text,criado_em timestamp,nomes_arquivos text);
