CREATE TABLE entregas_epi(id bigint PRIMARY KEY,funcionario_id bigint REFERENCES funcionarios(id),data_entrega date);
CREATE TABLE entrega_epi_itens(id bigint PRIMARY KEY,entrega_id bigint REFERENCES entregas_epi(id),epi_id bigint REFERENCES epis(id));
CREATE TABLE entregas_epis(id bigint PRIMARY KEY,funcionario_id bigint REFERENCES funcionarios(id),epi_id bigint REFERENCES epis(id),data_entrega date);
